-- Seed for the English Tenses module. Run after 0005_add_grammar_module.sql.
on conflict (id) do update set name = excluded.name, name_vi = excluded.name_vi, category = excluded.category, level = excluded.level, summary = excluded.summary, formula = excluded.formula, uses = excluded.uses, signals = excluded.signals, examples = excluded.examples, common_mistakes = excluded.common_mistakes, compare_with = excluded.compare_with, vocabulary = excluded.vocabulary, updated_at = now();

on conflict (id) do update set level = excluded.level, topic = excluded.topic, vietnamese = excluded.vietnamese, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, sort_order = excluded.sort_order;
